#include "resident/checkpoint/projection_writer.hpp"
// 完整回执始终来自同一永久舰队来源；业务层没有任意JSON热payload。
#include "naval_command_codec.hpp"
#include "resident/storage/common_codec.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <set>
#include <tuple>
namespace hanmo::resident::naval_command_codec {
namespace {
using V=BoundaryValue;
// 每船只读取原unit/人物/容器引用，未知第二套余额和占用字段直接拒绝。
NavalVesselAssignment assignment(const V& v){const StableId p="naval_form/assignment";boundary::fields(v,{"vessel_id","unit_id","passenger_ids","prisoner_ids","extra_inventory_ids"},{},p);NavalVesselAssignment a;a.vessel_id=boundary::get_string(v,"vessel_id",p);a.unit_id=boundary::get_string(v,"unit_id",p);a.passenger_ids=boundary::strings(boundary::field(v,"passenger_ids",p),p);a.prisoner_ids=boundary::strings(boundary::field(v,"prisoner_ids",p),p);a.extra_inventory_ids=boundary::strings(boundary::field(v,"extra_inventory_ids",p),p);a.field_order=boundary::order(v);return a;}
// 已存在的原序必须恰好覆盖七个明确键，不能用保存顺序掩藏身份。
Status valid(const NavalCommandReceipt& r){if((r.kind!="naval_form"&&r.kind!="naval_disband")||!naval_request_key_valid(r.request_key)||r.receipt_id.rfind("naval_action:",0)!=0||r.fleet_id.rfind("fleet:",0)!=0||r.army_id.empty()||r.actor_id.empty()||r.tick<0)return common_failure("InvalidNavalCommandReceipt");if(!r.field_order.empty()){std::set<StableId> fields={"kind","request_key","receipt_id","fleet_id","army_id","actor_id","tick"};if(r.field_order.size()!=fields.size())return common_failure("InvalidNavalReceiptFieldOrder");for(const auto& key:r.field_order)if(fields.erase(key)!=1)return common_failure("InvalidNavalReceiptFieldOrder");}return common_success();}
}
// 只解析两个已实现意图；同一命令不能夹带航行、钱货或修船参数。
Outcome<NavalCommand> decode_command(const V& v){try{const auto kind=boundary::get_string(v,"kind","naval");if(kind=="naval_form"){boundary::fields(v,{"kind","request_key","army_id","assignments"},{},kind);NavalForm f;f.request_key=boundary::get_string(v,"request_key",kind);f.formation.army_id=boundary::get_string(v,"army_id",kind);for(const auto& row:boundary::array(boundary::field(v,"assignments",kind),kind))f.formation.assignments.push_back(assignment(row));return {true,NavalCommand{std::move(f)},{}};}if(kind=="naval_disband"){boundary::fields(v,{"kind","request_key","fleet_id"},{},kind);return {true,NavalCommand{NavalDisband{boundary::get_string(v,"request_key",kind),boundary::get_string(v,"fleet_id",kind)}},{}};}return {false,{},common_failure("UnknownNavalCommand").error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
// 显示只投影已登记的命令结果，原世界位置和人物权源不隐藏在回执里。
// 报价只投影正式逐船载重和预算，不能把观察者/权限或候选状态送给客户端改写。
BoundaryValue encode_quote(const NavalCommandQuote& q){BoundaryValue::Array loads;Integer budget=0;if(q.formation){budget=q.formation->travel_budget;for(const auto& row:q.formation->loads)loads.push_back(boundary::obj({{"vessel_id",BoundaryValue{row.vessel_id}},{"unit_id",BoundaryValue{row.unit_id}},{"people",BoundaryValue{row.people}},{"working_crew",BoundaryValue{row.working_crew}},{"cargo_weight",BoundaryValue{row.cargo_weight}}}));}return boundary::obj({{"ok",BoundaryValue{true}},{"duration",BoundaryValue{Integer{0}}},{"naval",boundary::obj({{"replayed",BoundaryValue{q.replayed}},{"berth_id",BoundaryValue{q.berth_id}},{"travel_budget",BoundaryValue{budget}},{"loads",BoundaryValue{std::move(loads)}}})}});}
Status emit_receipt_fields(ProjectionWriter& w,const NavalCommandReceipt& r){auto checked=valid(r);if(!checked.ok)return w.reject(checked.error.original.code,"naval_receipt");w.field("kind",r.kind);w.field("request_key",r.request_key);w.field("receipt_id",r.receipt_id);w.field("fleet_id",r.fleet_id);w.field("army_id",r.army_id);w.field("actor_id",r.actor_id);w.field("tick",r.tick);w.order_fields(r.field_order);return w.status();}
BoundaryValue encode_receipt(const NavalCommandReceipt& r){BoundaryValue out;BoundaryProjectionWriter sink(out);auto written=sink.object("",[&](auto& w){return emit_receipt_fields(w,r);});if(!written.ok)boundary::fail(written.error.original.code,written.error.original.path);auto finished=sink.finish();if(!finished.ok)boundary::fail(finished.error.original.code,finished.error.original.path);return out;}
// 缓存输入未知键不吞；世界validator还须比对同一Naval原事实。
Outcome<NavalCommandReceipt> decode_receipt(const V& v){try{const StableId p="naval_receipt";boundary::fields(v,{"kind","request_key","receipt_id","fleet_id","army_id","actor_id","tick"},{},p);NavalCommandReceipt r;r.kind=boundary::get_string(v,"kind",p);r.request_key=boundary::get_string(v,"request_key",p);r.receipt_id=boundary::get_string(v,"receipt_id",p);r.fleet_id=boundary::get_string(v,"fleet_id",p);r.army_id=boundary::get_string(v,"army_id",p);r.actor_id=boundary::get_string(v,"actor_id",p);r.tick=boundary::get_int(v,"tick",p);r.field_order=boundary::order(v);auto checked=valid(r);if(!checked.ok)return {false,{},checked.error};return {true,std::move(r),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
// 未启用模块时外层不得调用此段，更不能在旧Common字节追加空存在位。
Status visit_receipt(CodecVisitor& c,NavalCommandReceipt& r){c.field("kind",r.kind);c.field("request_key",r.request_key);c.field("receipt_id",r.receipt_id);c.field("fleet_id",r.fleet_id);c.field("army_id",r.army_id);c.field("actor_id",r.actor_id);c.field("tick",r.tick);common_checkpoint::strings(c,"field_order",r.field_order);if(!c.status().ok)return c.status();auto checked=valid(r);return checked.ok?c.status():c.reject(checked.error.original.code);}
// 重哈希的缓存也必须与唯一事实身份、意图、请求人及原时刻完全一致。
Status validate_cached_receipt(const NavalAssetState& n,const NavalCommandReceipt& r,const StableId& actor){auto checked=valid(r);if(!checked.ok)return checked;for(const auto& f:n.fleets)if(f.id==r.fleet_id){const bool release=r.kind=="naval_disband";if(actor!=(release?f.release_actor_id:f.commander_actor_id)||r.actor_id!=actor||r.army_id!=f.army_id||r.request_key!=(release?f.release_request_key:f.request_key)||r.receipt_id!=(release?f.release_source_id:f.source_id)||r.tick!=(release?f.released_tick:f.created_tick))return common_failure("NavalCachedReceiptMismatch",r.receipt_id);return common_success();}return common_failure("NavalCachedSourceMissing",r.receipt_id);}
Status validate_cached_receipt(const MilitaryState& military,const NavalAssetState& n,const NavalCommandReceipt& r,const StableId& actor){auto checked=valid(r);if(!checked.ok)return checked;for(const auto& f:n.fleets)if(f.id==r.fleet_id){const bool release=r.kind=="naval_disband";auto original=naval_formation_actor(military,f);if(!original.ok)return {false,{},original.error};if(actor!=(release?f.release_actor_id:original.value)||r.actor_id!=actor||r.army_id!=f.army_id||r.request_key!=(release?f.release_request_key:f.request_key)||r.receipt_id!=(release?f.release_source_id:f.source_id)||r.tick!=(release?f.released_tick:f.created_tick))return common_failure("NavalCachedReceiptMismatch",r.receipt_id);return common_success();}return common_failure("NavalCachedSourceMissing",r.receipt_id);}

}
